import React from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import useFetch from '../../hooks/useFetch' // Dùng lại hook giống Dashboard
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   // Dùng useFetch y hệt như trang Dashboard
   const { data: users, loading, error } = useFetch(`${BASE_URL}/users`)

   const handleDelete = async (id) => {
      if(window.confirm("Xóa người dùng này?")) {
         // Logic xóa ở đây
      }
   }

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <h3 className="mb-4 fw-bold">Quản trị người dùng</h3>
                  
                  {loading && <h4 className="text-center">Đang tải dữ liệu...</h4>}
                  {error && <div className="alert alert-danger text-center">{error}</div>}

                  {!loading && !error && (
                     <Table hover responsive className="shadow-sm bg-white rounded">
                        <thead className="bg-light">
                           <tr>
                              <th>Tên người dùng</th>
                              <th>Email</th>
                              <th>Vai trò</th>
                              <th className="text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users?.map(user => (
                              <tr key={user._id}>
                                 <td>{user.username}</td>
                                 <td>{user.email}</td>
                                 <td>
                                    <Badge color={user.role === 'admin' ? 'danger' : 'success'}>
                                       {user.role}
                                    </Badge>
                                 </td>
                                 <td className="text-center">
                                    <Button color="danger" size="sm" onClick={() => handleDelete(user._id)}>
                                       <i className="ri-delete-bin-line"></i>
                                    </Button>
                                 </td>
                              </tr>
                           ))}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   )
}

export default ManageUsers
